import React from 'react';
import { Wrapper, Status } from '@googlemaps/react-wrapper';

const mapContainerStyle = {
  width: '100%',
  height: '400px'
};

const GoogleMapComponent = ({ cityData, heatZones, center }) => {
  const { isLoaded } = useJsApiLoader({
    id: 'google-map-script',
    googleMapsApiKey: process.env.REACT_APP_GOOGLE_MAPS_API_KEY || "YOUR_GOOGLE_MAPS_API_KEY"
  });

  const [map, setMap] = React.useState(null);

  const onLoad = React.useCallback(function callback(map) {
    setMap(map);
  }, []);

  const onUnmount = React.useCallback(function callback(map) {
    setMap(null);
  }, []);

  // Prepare heatmap data
  const heatmapData = heatZones?.map(zone => ({
    location: new window.google.maps.LatLng(zone.lat, zone.lng),
    weight: zone.intensity
  })) || [];

  if (!isLoaded) {
    return (
      <div className="flex items-center justify-center h-96 bg-gray-100 rounded-lg">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-gray-600">Loading map...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full">
      <GoogleMap
        mapContainerStyle={mapContainerStyle}
        center={center}
        zoom={11}
        onLoad={onLoad}
        onUnmount={onUnmount}
        options={{
          mapTypeId: 'hybrid',
          styles: [
            {
              featureType: 'all',
              elementType: 'geometry.fill',
              stylers: [{ visibility: 'on' }]
            }
          ]
        }}
      >
        {/* City center marker */}
        <Marker
          position={center}
          title={cityData?.city}
          icon={{
            url: 'https://maps.google.com/mapfiles/ms/icons/red-dot.png'
          }}
        />

        {/* Heat zones markers */}
        {heatZones?.map((zone, index) => (
          <Marker
            key={index}
            position={{ lat: zone.lat, lng: zone.lng }}
            title={`${zone.zone_type}: ${zone.temperature}°C`}
            icon={{
              url: zone.intensity > 0.7 ? 
                'https://maps.google.com/mapfiles/ms/icons/red-dot.png' :
                zone.intensity > 0.4 ?
                'https://maps.google.com/mapfiles/ms/icons/orange-dot.png' :
                'https://maps.google.com/mapfiles/ms/icons/yellow-dot.png'
            }}
          />
        ))}

        {/* Heatmap layer */}
        {heatmapData.length > 0 && (
          <HeatmapLayer
            data={heatmapData}
            options={{
              radius: 20,
              opacity: 0.6
            }}
          />
        )}
      </GoogleMap>
    </div>
  );
};

export default GoogleMapComponent;
